      <p class="subtitle">Select every answer you think applies. Each question supports multiple selections, so choose carefully before you submit.</p>
    </section>

    <form id="quiz-form">
      <div class="form-field">
        <fieldset>
          <legend>1. Which of these are commonly used for web page structure or styling?</legend>
          <p class="help-text">Pick all that fit. This question includes markup and styling technologies often used alongside programming languages on the web.</p>
          <div class="choice-list">
            <label class="choice">
              <input type="checkbox" name="q1" value="HTML">
              <span class="choice-text">HTML</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q1" value="CSS">
              <span class="choice-text">CSS</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q1" value="Python">
              <span class="choice-text">Python</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q1" value="Java">
              <span class="choice-text">Java</span>
            </label>
          </div>
        </fieldset>
      </div>

      <div class="form-field">
        <fieldset>
          <legend>2. Which languages are widely used for mobile app development?</legend>
          <div class="choice-list">
            <label class="choice">
              <input type="checkbox" name="q2" value="Swift">
              <span class="choice-text">Swift</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q2" value="Kotlin">
