            <label class="choice">
              <input type="checkbox" name="q2" value="Ruby">
              <span class="choice-text">Ruby</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q2" value="COBOL">
              <span class="choice-text">COBOL</span>
            </label>
          </div>
        </fieldset>
      </div>

      <div class="form-field">
        <fieldset>
          <legend>3. Which languages are commonly associated with systems programming?</legend>
          <div class="choice-list">
            <label class="choice">
              <input type="checkbox" name="q3" value="C">
              <span class="choice-text">C</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q3" value="Rust">
              <span class="choice-text">Rust</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q3" value="JavaScript">
              <span class="choice-text">JavaScript</span>
            </label>
            <label class="choice">
              <input type="checkbox" name="q3" value="Go">
              <span class="choice-text">Go</span>
            </label>
          </div>
        </fieldset>
      </div>

      <div class="actions">
        <button type="submit">Submit quiz</button>
        <output id="result" class="result" aria-live="polite"></output>
      </div>
    </form>
  </main>

  <script>
    const quizForm = document.getElementById("quiz-form");
    const result = document.getElementById("result");

    const answerKey = {
      q1: ["HTML", "CSS"],
      q2: ["Swift", "Kotlin"],
      q3: ["C", "Rust", "Go"]
    };

    function getSelectedValues(questionName) {
      return Array.from(document.querySelectorAll(`input[name="${questionName}"]:checked`))
        .map((input) => input.value)
        .sort();
