        const selected = getSelectedValues(questionName);
        const expected = [...answers].sort();

        if (arraysMatch(selected, expected)) {
          score += 1;
        }
      });

      result.innerHTML = `<strong>Score:</strong> ${score} / ${Object.keys(answerKey).length}`;
    });
